class MultiDecorateTests(TestCase):

    def test_multi_decorate_with_list_of_decorators(self):
        """
        Test multi_decorate with a list of decorators.
        """
        def dec1(func):
            def wrapper(*args, **kwargs):
                return "dec1:" + func(*args, **kwargs)
            return wrapper

        def dec2(func):
            def wrapper(*args, **kwargs):
                return "dec2:" + func(*args, **kwargs)
            return wrapper

        def my_func(*args, **kwargs):
            return "original"

        wrapped_func = _multi_decorate([dec1, dec2], my_func)
        self.assertEqual(wrapped_func(), "dec2:dec1:original")

    def test_multi_decorate_with_single_decorator(self):
        """
        Test multi_decorate with a single decorator.
        """
        def dec(func):
            def wrapper(*args, **kwargs):
                return "dec:" + func(*args, **kwargs)
            return wrapper

        def my_func(*args, **kwargs):
            return "original"

        wrapped_func = _multi_decorate(dec, my_func)
        self.assertEqual(wrapped_func(), "dec:original")

    def test_multi_decorate_with_decorator_that_adds_attribute(self):
        """
        Test multi_decorate with a decorator that adds an attribute.
        """
        class DecWithAttr:
            def __init__(self):
                self.attr = True

            def __call__(self, func):
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)
                wrapper.added_attr = self.attr
                return wrapper

        def my_func(*args, **kwargs):
            return "original"

        wrapped_func = _multi_decorate(DecWithAttr(), my_func)
        self.assertEqual(wrapped_func(), "original")
        self.assertTrue(hasattr(wrapped_func, 'added_attr'))
        self.assertTrue(wrapped_func.added_attr)

    def test_multi_decorate_with_bound_method(self):
        """
        Test multi_decorate with a bound method.
        """
        class MyClass:
            def my_method(self):
                return "original"

        def dec(func):
            def wrapper(*args, **kwargs):
                return "dec:" + func(*args, **kwargs)
            return wrapper

        instance = MyClass()
        bound_method = instance.my_method
        wrapped_method = _multi_decorate(dec, bound_method)
        self.assertEqual(wrapped_method(), "dec:original")
