class MethodDecoratorDecTests(SimpleTestCase):
    def test_dec_is_function(self):
        """
        Test that _dec is a function.
        """
        from django.utils.decorators import method_decorator
        self.assertIsInstance(method_decorator._dec, function)

    def test_dec_returns_decorated_object(self):
        """
        Test that _dec returns the decorated object.
        """
        from django.utils.decorators import method_decorator
        class Test:
            @method_decorator(lambda f: f)
            def method(self):
                return "original"
        self.assertEqual(Test().method(), "original")

    def test_dec_raises_value_error_when_name_is_missing_and_obj_is_class(self):
        """
        Test that _dec raises a ValueError when name is missing and obj is a class.
        """
        from django.utils.decorators import method_decorator
        class Test:
            pass
        with self.assertRaises(ValueError) as context:
            method_decorator._dec(Test)
        self.assertEqual(str(context.exception), "The keyword argument `name` must be the name of a method of the decorated class: <class '__main__.Test'>. Got '' instead.")

    def test_dec_raises_type_error_when_name_is_not_callable(self):
        """
        Test that _dec raises a TypeError when name is not callable.
        """
        from django.utils.decorators import method_decorator
        class Test:
            prop = 1
        with self.assertRaises(TypeError) as context:
            method_decorator._dec(Test, name='prop')
        self.assertEqual(str(context.exception), "Cannot decorate 'prop' as it isn't a callable attribute of <class '__main__.Test'> (1).")

    def test_dec_handles_multiple_decorators(self):
        """
        Test that _dec handles multiple decorators.
        """
        from django.utils.decorators import method_decorator
        def dec1(f):
            def wrapper(*args, **kwargs):
                return f(*args, **kwargs) + "1"
            return wrapper
        def dec2(f):
            def wrapper(*args, **kwargs):
                return f(*args, **kwargs) + "2"
            return wrapper
        @method_decorator((dec1, dec2), name='method')
        class Test:
            def method(self):
                return "original"
        self.assertEqual(Test().method(), "original21")
